  ["highground.coachpreferences.choose_text_sound_or_both.306e9e"] = "Elige texto, sonido o ambos",
  ["highground.coachpreferences.highground_is_the_only_download_you_need.f138df"] = "Highground es la única descarga que necesitas",
  ["highground.coachpreferences.addons_brings_the_addon_switches_settings_shortcuts.df8aff"] = "Accesorios reúne los interruptores de los accesorios, los accesos directos a ajustes y las guías. Elimina cualquier descarga independiente aparte. Conserva todas las carpetas de módulos y los dos accesorios de datos necesarios. Desactivar un accesorio de datos impide que Highground se cargue.",
